  font-family: "Trebuchet MS", "Arial Narrow", sans-serif;
}

.game {
  min-height: 100vh;
  position: relative;
  overflow: hidden;
}

.arena {
  min-height: 100vh;
  background:
    radial-gradient(circle at 50% 42%, rgba(242, 209, 142, 0.08), transparent 24%),
    linear-gradient(180deg, #33404d, #171b20 58%);
}

.enemy,
.player {
  position: absolute;
  padding: 18px 24px;
  border: 2px solid rgba(246, 239, 228, 0.72);
  border-radius: 8px;
  background: rgba(6, 9, 12, 0.18);
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.16);
}

.enemy {
  right: 28%;
  top: 28%;
}

.player {
  left: 34%;
  bottom: 24%;
}

