  position: absolute;
  inset: 16px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 16px;
  pointer-events: none;
}

.hud-top,
.hud-bottom {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}

