  align-items: flex-end;
}

.objective-chip,
.pickup-chip,
.vitals-card,
.alert-pill {
  backdrop-filter: blur(10px);
  box-shadow: var(--hud-shadow);
}

.objective-chip,
.pickup-chip {
  max-width: min(320px, 52vw);
  padding: 10px 14px;
  border: 1px solid var(--hud-border);
  border-radius: 14px;
  background: var(--hud-bg-soft);
}

.pickup-chip {
  text-align: right;
}

.alert-pill {
  max-width: min(360px, 55vw);
  padding: 12px 16px;
  border: 1px solid var(--danger-border);
  border-radius: 999px;
  background: linear-gradient(135deg, var(--danger-bg), rgba(18, 10, 9, 0.9));
  animation: alertPulse 1.8s ease-in-out infinite;
}

.alert-pill[data-tone="warning"] {
  border-color: rgba(241, 194, 123, 0.28);
  background: linear-gradient(135deg, rgba(79, 52, 18, 0.88), rgba(18, 11, 8, 0.9));
  animation-duration: 2.4s;
}

.vitals-card {
  width: min(320px, calc(100vw - 32px));
  padding: 14px;
  border: 1px solid var(--hud-border);
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(9, 12, 16, 0.9), rgba(8, 12, 16, 0.68));
}

.vitals-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 12px;
}

