    transform: translateY(-1px);
    box-shadow: 0 20px 42px rgba(0, 0, 0, 0.34);
  }
}

@media (max-width: 720px) {
  .hud-top,
  .hud-bottom {
    flex-direction: column;
    align-items: stretch;
  }

  .hud-bottom {
    align-items: stretch;
  }

  .objective-chip,
  .pickup-chip,
  .alert-pill,
  .vitals-card {
    max-width: none;
  }

  .pickup-chip {
    text-align: left;
  }
}

@media (prefers-reduced-motion: reduce) {
  .alert-pill,
  .meter-fill {
    animation: none;
    transition: none;
  }
}

